"""Durable exact-scope review record; does not author unassigned commentary."""
from pathlib import Path
from datetime import datetime,timezone
import json,re,hashlib,xml.etree.ElementTree as E,sys
W=Path(__file__).resolve().parent;D=W/'sources/review-p72-p89a'
IDS=['p72','p73','p74','p75','p76','p77','p78','p79','p80','p81','p81a','p82','p83','p84','p85','p86','p87','p88','p89','p89a']
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
sht=lambda s:hashlib.sha256(s.encode()).hexdigest()
def save(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
def blocks():
 d={}
 for p in sorted((W/'commentary').glob('*.md')):
  for m in re.finditer(r'^=== (\S+)\n(.*?)(?=^=== |\Z)',p.read_text(),re.M|re.S):
   assert m[1] not in d;d[m[1]]=m[2].strip()
 return d
notes={
'p72':('corrected','Alle vier Absätze und den selektiven ZPO-Verweis gelesen. Gesetzlicher Ausschluss, Befangenheit, Antrag/Glaubhaftmachung und Zuständigkeit präzisiert; §§ 45/46 ZPO nicht pauschal importiert. Konkrete Amtsmitwirkung von früherer Beschäftigung beim DPMA getrennt; § 83 Abs. 3 Nr. 2 korrekt eingegrenzt.'),
'p73':('corrected','Beide Absätze geprüft. Amtsermittlung, spezielle Nachweisverteilung und Vorbereitung auch ohne mündliche Verhandlung unterschieden. Tatsächlich gelesenen § 273 Abs. 2, Abs. 3 Satz 1 und Abs. 4 Satz 1 ZPO entfaltet; keine pauschale Übernahme weiterer Sätze. Benachrichtigung über Anordnungen und Gehörsgrenze ausdrücklich ergänzt.'),
'p74':('retained','Alle drei Absätze geprüft: nicht abschließende Beweismittelliste, geeignete vorbereitende Aufnahme durch Mitglied oder ersuchtes Gericht mit einzelnen Beweisfragen sowie Benachrichtigung, Teilnahme und sachdienliche Fragen. Befragungsbeispiel zutreffend; Gutachten nicht bindend. Kein Anspruch auf beliebige Beweisaufnahme behauptet.'),
'p75':('retained','Beide Absätze vollständig gelesen. Mindestladungsfrist von zwei Wochen, Abkürzung durch Vorsitz nur bei Dringlichkeit, erforderlicher Ausbleibenshinweis und mögliche Entscheidung ohne Beteiligten korrekt. Beispiel trennt persönliche Verhinderung von gerichtlicher Terminentscheidung; kein automatischer Fortfall jeder Entscheidung bei Ladungsmangel behauptet.'),
'p76':('retained','Alle sechs Absätze gelesen: Eröffnung/Leitung, wesentlicher Aktenvortrag, Anträge und Begründung, tatsächliche/rechtliche Erörterung, Fragen der Senatsmitglieder und Senatsentscheidung bei Beanstandung sowie Schließung/Wiedereröffnung. Beispiel unterscheidet Vergleichsüberlegung und bindende Antragsbeschränkung; § 77/78 stimmen.'),
'p77':('corrected','Beide Absätze und §§ 160–165 ZPO tatsächlich gelesen. Pflicht zur Niederschrift bleibt auch ohne Schriftführer; Beweisaufnahme erfasst. Aufzeichnung, Genehmigung, Unterschriften und Berichtigung ergänzt. § 165-Beweiskraft auf Förmlichkeiten begrenzt; jederzeitige Protokollberichtigung von zweiwöchiger Tatbestandsberichtigung nach § 80 getrennt.'),
'p78':('corrected','Alle drei Absätze geprüft. Freie Überzeugung und Begründung, Äußerungsmöglichkeit und Zustimmung bei Richterwechsel erhalten. BGH I ZB 93/11 im gesamten Volltext gelesen: Vertrauen auf angekündigte Begründung und Information über einseitiges Telefonat konkret erläutert; keine allgemeine feste Wartefrist oder Beratungsterminankündigung abgeleitet.'),
'p79':('retained','Beide Absätze vollständig gelesen. Verkündung im Schluss- oder sofort anzuberaumenden Termin, Sollgrenze drei Wochen mit wichtigen Gründen, alternative Zustellung und Amtszustellung auch nach Verkündung zutreffend unterschieden. Begründung für Zurückweisungen und Rechtsmittelentscheidungen sowie Abgrenzung zur Berichtigung sachgerecht.'),
'p80':('corrected','Alle fünf Absätze geprüft. Die zuvor als bloßes Erlauben bezeichnete Berichtigung offenbarer Fehler als gesetzliche Pflicht korrigiert; kein Antrag als Voraussetzung hinzugefügt. Zweiwochenfrist anderer Tatbestandsfehler, Entscheidung ohne Verhandlung/ohne Beweisaufnahme, ursprüngliche Richter und Vermerk präzisiert. § 77-Protokollberichtigung abgegrenzt.'),
'p81':('corrected','Alle sechs Absätze, zwei Vertretungsgruppen und Änderung 2026 I Nr. 152 Art. 14 Nr. 1 gelesen. Beschäftigten-/Behördenvertretung und Unentgeltlichkeitsbedingung der zweiten Gruppe, Zurückweisung und gesonderte Untersagung erklärt. Allgemeine Befugnis und Vollmacht getrennt. Seit 01.10.2026 Vollstreckungsorgane nur in Kontrolle nach Abs. 6 Satz 2 einbezogen.'),
'p81a':('corrected','Beide Absätze, §§ 114–116 ZPO, § 130 Abs. 2/3 und §§ 133–137 PatG gelesen. Bedürftigkeit/Erfolg/Mutwilligkeit, Sonderregeln juristischer Personen, Beiordnung, gemeinsame Antragsteller, Gebührenhemmung und spätere Veränderung präzisiert. Gebührenfrist nicht als allgemeine Rechtsmittelfrist behandelt. BGH I ZA 14/10 zur Nebenentscheidung volltextgeprüft; heutiger § 81a nicht rückwirkend zugeschrieben.'),
'p82':('corrected','Alle vier Absätze und aktuelle §§ 227, 752a, 753a ZPO gelesen. Ausgenommener sommerlicher Verlegungsanspruch, subsidiäre Anwendung, getrennte Kostengesetze, begrenzte Drittakteneinsicht und fehlender allgemeiner Zusatzrechtsweg konkretisiert. Art. 14 Nr. 2/Art. 18 Abs. 1 BGBl. 2026 I Nr. 152 geprüft. Versicherung erteilter Vollmacht in Textform ersetzt Nachweis, nicht Vollmacht; Wirkung bei Erlöschensanzeige erklärt.'),
'p83':('corrected','Alle drei Absätze und sechs Rügegründe geprüft. Zulassungspflicht, Beschwerdegegenstand statt Nebenentscheidung, fehlende statt bloß unrichtige Gründe und genehmigte Vertretung präzisiert. Zwei BGH-Volltexte stützen eng begrenzte Aussagen. Statthaftigkeit einer ausgeführten Rüge von ihrer Begründetheit getrennt; mögliche Entscheidungserheblichkeit und Reaktion auf fehlenden Hinweis erläutert.'),
'p84':('retained','Beide Absätze und aktuelle §§ 546/547 ZPO gelesen. Berechtigung der bisherigen Beteiligten, Rechtsverletzung und Beruhen sowie Tatsachenbindung nach § 89 Abs. 2 zutreffend. Neues Gutachten als solches kein Rechtsfehler; Statthaftigkeit nach § 83 bleibt eigenständig. Keine uneingeschränkte zweite Tatsacheninstanz behauptet.'),
'p85':('corrected','Alle fünf Absätze, drei Begründungsanforderungen und § 142-Verweis gelesen. Einlegung binnen Monatsfrist beim BGH, Beginn der Begründungsfrist schon mit Einlegung, nur deren Verlängerbarkeit und BGH-Anwalt konkretisiert. Patentanwalt erhält auf Antrag Wort, ersetzt Vertreter nicht. Gesetzliche Gebühr/notwendige Auslagen von privatem Honorar und Kostenlast nach § 90 getrennt.'),
'p86':('retained','Gesamten Wortlaut geprüft. Amtsprüfung von Statthaftigkeit, Form und Frist beider Handlungen sowie gebundene Unzulässigkeitsverwerfung korrekt. Fristgerechte Einlegung allein genügt nicht; Wiedereinsetzung zutreffend dem § 88-Regime zugeordnet. Kein sachlicher Erfolg als Ersatz für Zulässigkeit dargestellt.'),
'p87':('retained','Beide Absätze und § 68 Abs. 1 gelesen. Mehrparteienzustellung, bestimmte Erklärungsfrist, schriftliche Erklärung beim BGH, Einlegungsdatum und Sollpflicht beglaubigter Abschriften sowie Stellungnahme nicht beteiligter Amtsleitung korrekt erfasst. Keine neue Tatsacheninstanz oder Gleichstellung privater Mitteilung mit Amtszustellung behauptet.'),
'p88':('corrected','Beide Absätze, §§ 233–238 ZPO und § 138 PatG tatsächlich gelesen. Selektive Verweisungsgruppen und BGH-Anwaltszwang erklärt. Zweiwöchige Wiedereinsetzung bzw. einmonatige Frist bei versäumter Begründung statt § 91-Zweimonatsfrist konkretisiert; Nachholung/Glaubhaftmachung und Zwischenbenutzerschutz getrennt. Hilfeantrag, Erfolgsaussicht und nur BGH-Anwalt bei Beiordnung erläutert.'),
'p89':('corrected','Alle vier Absätze gelesen. Beschluss ohne notwendige mündliche Verhandlung, Tatsachenbindung mit konkreter Rügeausnahme, Begründung/Amtszustellung und zwingende Zurückverweisung bei Aufhebung erläutert. BGH I ZB 93/11 tatsächlichen Tenor/Rn. 24–28 zugeordnet: keine abschließende Kostenentscheidung. Bindung nur an die Aufhebung tragende rechtliche Beurteilung präzisiert.'),
'p89a':('corrected','Gesamte Norm und § 321a Abs. 2–5 ZPO gelesen. Beschwerte Partei, eigenes entscheidendes Gericht, Entscheidungserheblichkeit, Ausschluss vorgelagerter Entscheidungen und BGH-Kontext präzisiert. Zweiwochen-Notfrist ab Kenntnis, Glaubhaftmachung, Jahresgrenze, Gericht/Form/Inhalt sowie Verwerfung/Zurückweisung und begrenzte Fortführung ergänzt. Keine allgemeine neue Sachinstanz versprochen.')}
assert set(notes)==set(IDS)
base=json.loads((D/'commentary-baseline.json').read_text());before=base['commentary'];current=blocks()
assert set(current)==set(before);changed=[i for i in current if before[i]!=current[i]]
assert len(changed)==13 and set(changed)<=set(IDS)
for i in IDS:assert (i in changed)==(notes[i][0]=='corrected')
u={x['id']:x for x in map(json.loads,(W/'units.jsonl').read_text().splitlines())}
r=E.parse(D/'markeng.xml').getroot();ns={n.attrib['doknr']:n for n in r.findall('norm')};compact=lambda s:re.sub(r'\s+','',s)
findings=[]
for i in IDS:
 x=u[i];n=ns[x['xml_doknr']];assert compact(x['text'])==compact(''.join(n.find('textdaten/text/Content').itertext()))
 findings.append(dict(id=i,label=x['label'],outcome=notes[i][0],finding=notes[i][1],resolved=True,source_xml_doknr=x['xml_doknr'],statutory_text_sha256=sht(x['text']),commentary_before_sha256=sht(before[i]),commentary_after_sha256=sht(current[i])))
cases=[]
for name,date,docket,scope,support,card,limit in [('gehoer','2013-04-11','I ZB 93/11','Tenor und vollständige Gründe Rn. 1–28 sowie Namenszeilen',['p78','p83','p89'],'bgh-gehoer-schriftverfahren','Current §§ 78(2), 83(3)(3), 89(4) retain relied-on rules; historical costs and use requirements not imported; original costs dispute not finally decided.'),('vkh','2010-07-01','I ZA 14/10','Tenor und vollständige Gründe Rn. 1–8 sowie Namenszeilen',['p81a','p82','p83','p88'],'bgh-vkh-nebenentscheidung','Current § 83 gateway persists; modern § 81a separately sourced, not retroactively attributed to 2010; no historical fee or substantive cancellation law imported.')]:
 c=E.parse(D/(name+'.xml')).getroot();assert c.findtext('aktenzeichen')==docket and not c.findtext('ecli');local=compact((D/(name+'-local.md')).read_text());count=0
 for tag in ['tenor','gruende']:
  for p in c.findall('.//'+tag+'//p'):
   t=''.join(p.itertext()).strip()
   if t:assert compact(t) in local;count+=1
 cases.append(dict(court='BGH',date=date,docket=docket,ecli=None,ecli_note='Official XML field empty; no ECLI invented',read_full_text=True,read_scope=scope,supported_reviewed_ids=support,official_xml='sources/review-p72-p89a/'+name+'.xml',official_xml_sha256=sha(D/(name+'.xml')),corpus_path='sources/review-p72-p89a/'+name+'-local.md',corpus_sha256=sha(D/(name+'-local.md')),nonempty_official_paragraphs_compared=count,missing_from_read_corpus=0,card='cases/'+card+'.md',superseded_law_check=limit))
now=datetime.now(timezone.utc).isoformat();prior=json.loads((D/'prior-review-result.json').read_text());assert prior['complete'] and set(prior['reviewed_ids']).isdisjoint(IDS)
status=json.loads((W/'status.json').read_text());cumulative=list(dict.fromkeys(status['cumulative_reviewed_ids']+IDS));assert len(cumulative)==100
coverage=json.loads((W/'completeness-independent.json').read_text());assert coverage['ok'];q=json.loads((W/'quality-report.json').read_text())
assert not any(q[k] for k in ['broken_local_links','exact_repeated_paragraphs','repeated_long_sentences','placeholder_matches'])
limitations=['Completion applies only to exactly 20 assigned units p72–p89a including p81a. Previous 80 reviewed units preserved without renewed substantive review; 91 units await second pass. No whole-book completion.', 'Selective case research: two BGH decisions read in full in local corpus and fresh official XML. Seven previous case cards retained without renewed substantive review. No new sufficiently specific case selected for the remaining 14 assigned units; no assertion that none exists.', 'Current official MarkenG consolidation, both 2026 amending articles and actual commencement clauses checked. §§ 81/82 changes effective 1 October 2026. Supplementary later-law search is not an exhaustive legislative pipeline audit.', 'Limited external ZPO/PatG individual-provision checks support the concrete explanations; no complete historical reconstruction or independent commentary of those codes, SGB amounts, all regulations, or every nested reference. No unverified fee amounts introduced.', 'Technical literal agreement, coverage, length, repetition and link checks do not establish legal errorlessness or external professional approval.']
validated='--validated' in sys.argv;technical=json.loads((W/'validation.json').read_text()) if validated else None
if validated:assert technical['ok'] and technical['verbatim_ratio']==1.0
result=dict(complete=validated,task='bounded_independent_second_pass',units_reviewed=20,reviewed_ids=IDS,decisive_date='2026-10-19',reviewed_at=now,unresolved_blockers=[],findings=findings,limitations=limitations,changed_ids=changed,retained_ids=[i for i in IDS if i not in changed],whole_book_complete=False,work_baseline_commit=base['work_baseline_commit'],baseline_evidence='sources/review-p72-p89a/commentary-baseline.json',baseline_evidence_sha256=sha(D/'commentary-baseline.json'),unchanged_unassigned_units=171,unassigned_commentary_unchanged=True,prior_review_result='sources/review-p72-p89a/prior-review-result.json',cumulative_reviewed_units=100,cumulative_reviewed_ids=cumulative,remaining_second_pass_units=91,case_checks=cases,source_preflight='preflight-result.json',source_verification='sources/verification.json',technical_validation=technical,technical_validation_pending=not validated,completeness=dict(expected=coverage['expected_count'],parsed=coverage['parsed_count'],missing=coverage['missing'],extra=coverage['unexpected'],xml_character_mismatch=coverage['xml_character_mismatch']),quality=dict(broken_links=q['broken_local_links'],repeated_long_sentences=q['repeated_long_sentences'],placeholder_matches=q['placeholder_matches']))
save(W/'review-result.json',result)
status.update(stage='bounded_second_pass_complete' if validated else 'bounded_second_pass_validation_pending',task_scope='Exactly p72–p89a including p81a; no whole-book completion.',reviewed_ids=IDS,units_reviewed=20,review_result='review-result.json',review_completed_at=now if validated else None,whole_book_review_complete=False,independent_second_pass='Current assigned 20 reviewed; 100 cumulatively reviewed, 91 pending',updated_at=now,remaining_limitations=limitations,unresolved_blockers=[],cumulative_reviewed_ids=cumulative,cumulative_reviewed_units=100,remaining_second_pass_units=91,commentary_characters=sum(map(len,current.values())))
status['source_checks']['latest_verification']=json.loads((W/'sources/verification.json').read_text())['last_verified_at']
status['case_law_sources']=[x for x in status['case_law_sources'] if x['docket'] not in [c['docket'] for c in cases]]+[{k:c[k] for k in ['court','date','docket','card','read_full_text']} for c in cases]
status['case_law_provenance']='Two BGH cases fully read and freshly verified in this batch; seven previous cards retained without renewed substantive review.'
status['quality_checks'].update(output_local_links=q['checked_output_links'],broken_links=q['broken_local_links'],repeated_paragraphs=q['exact_repeated_paragraphs'],repeated_long_sentences=q['repeated_long_sentences'],other_commentary_blocks='All 171 unassigned commentary blocks unchanged against baseline '+base['work_baseline_commit'],unchanged_commentary_units=178,retained_reviewed_units=7,corrected_reviewed_units=13)
if validated:status['validation_result']=technical
save(W/'status.json',status)
fetches=json.loads((D/'fetches.json').read_text());verification=json.loads((W/'sources/verification.json').read_text())
for f in fetches:
 assert sha(W/f['path'])==f['sha256']
 if f['path'] not in {x['path'] for x in verification['fetches']}:verification['fetches'].append(f)
verification['bounded_review_p72_p89a']['case_checks']=cases
save(W/'sources/verification.json',verification)
support=set().union(*(set(c['supported_reviewed_ids']) for c in cases))
search=dict(checked_at=now,queries=[dict(query='site:rechtsprechung-im-internet.de MarkenG 83 Gehör 78',result='Firecrawl: No results found; exit 0, no result file. Decisions instead located in local national corpus, then fresh official XML downloaded.'),dict(query='Markengesetz Änderung Oktober 2026 BGBl',evidence='sources/review-p72-p89a-amendments-search.json',result='Official current consolidated MarkenG among results; commercial snippets not used as legal proof. No evidenced later MarkenG amendment; selective search only.')],local_corpus_query='rg -l § 83.*MarkenG|§ 89a.*MarkenG in /Volumes/LaCie/law-intake/eu/de/rii; inspected candidate metadata, selected and fully read JURE130017836 and JURE100067758 for direct relevance',case_checks=cases,fresh_fetches='sources/review-p72-p89a/fetches.json',no_new_case_selected_ids=[i for i in IDS if i not in support],limit=limitations[1])
save(D/'search-log.json',search);log=json.loads((W/'sources/search-log.json').read_text());log['bounded_review_p72_p89a']=search;save(W/'sources/search-log.json',log)
manifest=dict(created_at=now,primary_statute='markeng.xml',canonical_statute='canonical.md',files=[dict(path=str(p.relative_to(W)),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted((W/'sources').rglob('*')) if p.is_file() and p.name!='manifest.json']);save(W/'sources/manifest.json',manifest)
print(json.dumps(dict(complete=validated,units_reviewed=20,corrected=13,retained=7,unassigned_unchanged=171,case_paragraph_counts=[c['nonempty_official_paragraphs_compared'] for c in cases],whole_book_complete=False)))
